import {works, experiences, notes} from '../desk-data.mjs';
import {education} from '../desk-background.mjs';
import {organisations, credentials, experienceTags} from '../desk-affiliations.mjs';
import {music, desk} from '../desk-config.mjs';

const iconNames=['menu','house','file-text','graduation-cap','layers','notebook','sun','moon','arrow-left','arrow-up-right','panel-left','search','x','chevron-right','chevron-left','play','pause','type','external-link','download'];
const icons=Object.fromEntries(await Promise.all(iconNames.map(async n=>[n,(await import(`./icons/${n}.js`)).default])));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(icons[n]??[]).map(([tag,attrs])=>`<${tag} ${Object.entries(attrs).map(([k,v])=>`${k}="${esc(v)}"`).join(' ')} />`).join('')}</svg>`;
const shell=document.querySelector('#shell'),audio=document.querySelector('#audio');
let prefs={lang:'zh',theme:'light',large:false,collapsed:false};
try{Object.assign(prefs,JSON.parse(localStorage.getItem('ty-leaves-prefs')||'{}'));}catch{}
if(!['zh','en'].includes(prefs.lang))prefs.lang='zh';
if(!['light','dark'].includes(prefs.theme))prefs.theme='light';
let mobileOpen=false,query='',paperFilter='all',backgroundFilter='all',musicError='',previousHash=location.hash||'#home';
const scrollPositions=new Map(), queries=new Map();
const t=(zh,en)=>prefs.lang==='zh'?zh:en;
const pick=x=>x?.[prefs.lang]??x??'';
const para=x=>(Array.isArray(x)?x:[]).map(s=>`<p>${esc(s)}</p>`).join('');
const a=(href,label,cls='')=>`<a class="${cls}" href="${esc(href)}">${label}</a>`;
const asset=file=>`../desk-assets/${file}`;
const orgShort={polyu:'PolyU',tsinghua:'Tsinghua',smart:'SMART',cas:'CAS',polysmart:'PolySmart',iluvatar:'Iluvatar',qiyuan:'启元实验室','royal-plaza':'Royal Plaza','x-institute':'X-Institute',hksar:'HKSAR',hkcc:'HKCC',cpce:'CPCE'};
const extraMarks={hkcc:'assets/hkcc.svg',cpce:'assets/cpce-logo-2.png',hksar:'assets/govhk.jpg'};
const orgMark=o=>extraMarks[o.id]??(o.mark?asset('pins/'+o.mark):null);
const papers=works.filter(w=>w.kind==='paper'),projects=works.filter(w=>w.kind==='project');
const navItems=[['home','house',()=>t('首页','Home')],['papers','file-text',()=>t('论文','Papers')],['background','graduation-cap',()=>t('学习与经历','Background')],['projects','layers',()=>t('项目','Projects')],['notes','notebook',()=>t('随手记','Notes')]];
const paths=()=>{try{return (decodeURIComponent(location.hash.slice(1))||'home').split('/');}catch{return ['missing'];}};
const section=()=>{const [p,id]=paths();if(['paper','work'].includes(p))return works.find(w=>w.id===id)?.kind==='project'?'projects':'papers';if(p==='note')return 'notes';if(p==='experience')return 'background';return p;};
const label=p=>navItems.find(x=>x[0]===p)?.[2]()??t('全部内容','All content');
const save=()=>{try{localStorage.setItem('ty-leaves-prefs',JSON.stringify(prefs));}catch{}};
function musicButton(compact=false){return `<button class="${compact?'rail-play':'play-button'}" data-play aria-label="${audio.paused?t('播放试听','Play preview'):t('暂停试听','Pause preview')}" aria-pressed="${!audio.paused}">${icon(audio.paused?'play':'pause')}</button>`;}
function player(){return `<section class="player" aria-label="${t('音乐试听','Music preview')}">${musicButton()}<div><span>${esc(music.title)} · ${esc(music.artist)}</span><small data-audio-state>${musicError||t('约 30 秒 · 官方试听','~30 seconds · Official preview')}</small></div><a href="${esc(music.sourceUrl)}" target="_blank" rel="noopener noreferrer" aria-label="${t('歌曲来源','Track source')}">${icon('arrow-up-right')}</a></section>`;}
function nav(){return `<aside class="sidebar" id="navigation" aria-label="${t('网站导航','Site navigation')}"><button class="nav-toggle icon-button" data-menu aria-controls="nav-links" aria-expanded="${!prefs.collapsed||mobileOpen}" aria-label="${t('展开或收起导航','Toggle navigation')}">${icon('panel-left')}</button>${a('#home','TY H.','rail-brand')}<nav id="nav-links">${navItems.map(([id,ic,text])=>`<a href="#${id}" class="nav-item ${section()===id?'active':''}" ${section()===id?'aria-current="page"':''} title="${esc(text())}">${icon(ic)}<span>${text()}</span></a>`).join('')}<a href="#index" class="nav-item ${section()==='index'?'active':''}" title="${t('查找所有内容','Search all content')}">${icon('search')}<span>${t('查找','Find')}</span></a></nav><div class="rail-bottom">${musicButton(true)}<span class="rail-track">${esc(music.title)}<small>${t('试听','Preview')}</small></span></div></aside><button class="nav-scrim" data-close-menu aria-label="${t('关闭导航','Close navigation')}" ${mobileOpen?'':'hidden'}></button>`;}
function toolbar(){return `<header class="toolbar"><button class="mobile-menu icon-button" data-menu aria-label="${t('打开导航','Open navigation')}" aria-expanded="${mobileOpen}">${icon('menu')}</button><div class="breadcrumbs">${a('#home',t('首页','Home'))}${section()!=='home'?`${icon('chevron-right')}<span>${label(section())}</span>`:''}</div><div class="settings"><span class="global-audio" data-global-player></span><a class="icon-button" href="#index" aria-label="${t('查找内容','Find content')}">${icon('search')}</a><button data-lang title="${t('切换语言','Switch language')}">${t('EN','中文')}</button><button data-size aria-label="${t('切换大字','Toggle larger text')}" aria-pressed="${prefs.large}">${icon('type')}</button><button data-theme aria-label="${t('切换明暗','Toggle theme')}" aria-pressed="${prefs.theme==='dark'}">${icon(prefs.theme==='dark'?'sun':'moon')}</button></div></header>`;}
function orgTile(o,home=false,selected=false){const src=orgMark(o);return `<a class="org-sticker ${selected?'selected':''} ${src?'':'word-sticker'}" href="#background/${o.id}" aria-label="${esc(pick(o.name))}" ${selected?'aria-current="true"':''} title="${esc(pick(o.name))}">${src?`<img src="${src}" alt="" width="110" height="60">`:`<span class="wordmark">${esc(orgShort[o.id])}</span>`}<span class="org-label">${esc(orgShort[o.id])}</span></a>`;}
function home(){return `<section class="home-intro"><div><p class="eyebrow">${t('这里是','HELLO, I’M')}</p><h1>Tin-Yeh Huang</h1><p>${t('一些接触过、参与过的东西，也留一点随手写的。','Some things I have worked on or spent time with, and a few notes along the way.')}</p></div><p class="intro-side">${esc(pick(desk.intro.study))}</p></section><section class="leaves" aria-label="${t('网站内容入口','Explore the website')}"><article class="leaf leaf-papers"><a href="#papers" class="leaf-top"><span class="leaf-number">01</span><h2>${t('论文','Papers')}</h2><p>${t('论文、预印本与通信。','Papers, preprints & correspondence.')}</p></a><a href="#papers" class="paper-fan" aria-label="${t('浏览全部论文','Browse all papers')}">${papers.filter(w=>w.thumb).map(w=>`<img src="${asset(w.thumb)}" alt="" width="180" height="240">`).join('')}</a><a class="leaf-foot" href="#papers"><span>${papers.length} ${t('项记录','records')}</span>${icon('arrow-up-right')}</a></article><article class="leaf leaf-background"><a href="#background" class="leaf-top"><span class="leaf-number">02</span><h2>${t('学习与经历','Studies & experiences')}</h2><p>${t('读过的学校，待过的地方。','Schools, places, and things along the way.')}</p></a><div class="home-organisations">${organisations.map(o=>orgTile(o,true)).join('')}</div><a class="leaf-foot" href="#background"><span>${t('看这里的记录','Explore the records')}</span>${icon('arrow-up-right')}</a></article><article class="leaf leaf-projects"><a href="#projects" class="leaf-top"><span class="leaf-number">03</span><h2>${t('项目','Projects')}</h2><p>${t('做过，也参与过。','Made, and taken part in.')}</p></a><a href="#work/ninetoothed" class="project-preview"><span>NineToothed</span><p>${t('工具移植、教学材料和演示。','Tooling, teaching materials, and demos.')}</p><small>${t('工作记录','Work record')}</small></a><a class="leaf-foot" href="#projects"><span>${t('打开项目','Explore projects')}</span>${icon('arrow-up-right')}</a></article><article class="leaf leaf-notes"><a href="#notes" class="leaf-top"><span class="leaf-number">04</span><h2>${t('随手记','Notes')}</h2><p>${t('留下一些没写定的东西。','A few things still taking shape.')}</p></a><a class="note-slip" href="#note/simple"><span>${t('简约就一定好吗','Is simpler always better?')}</span><p>${t('简约不代表就是好的设计。','Simplicity does not automatically make a design good.')}</p><small>${t('整理稿','Draft')}</small></a><a class="leaf-foot" href="#notes"><span>${t('翻开笔记','Read the notes')}</span>${icon('arrow-up-right')}</a></article></section><section class="home-lower"><a href="#note/website" class="latest"><small>${t('这阵子','Lately')}</small><span>${t('在改这个网站。','Working on this website.')}</span>${icon('arrow-up-right')}</a>${player()}</section>`;}
function heading(title,desc='',over=''){return `<header class="scene-heading">${over?`<p class="eyebrow">${over}</p>`:''}<h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</header>`;}
function links(w){return `<div class="source-links">${(w.links??[]).map(([txt,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(txt)}${icon('arrow-up-right')}</a>`).join('')}</div>`;}
function workRow(w){return `<article class="work-row"><a href="#work/${w.id}" class="work-title"><span class="record-year">${esc(w.year)}</span><div><h2>${esc(pick(w.title))}</h2><p>${esc(w.context)}</p></div>${icon('arrow-up-right')}</a><p class="record-version">${esc(pick(w.version))}</p></article>`;}
function workList(project=false){const list=project?projects:papers;return `${heading(project?t('项目','Projects'):t('论文','Papers'),project?t('工具、教学与参与过的工作。','Tooling, teaching, and work I have taken part in.'):t('发表记录、预印本与通信，版本和来源留在每个条目里。','Publication records, preprints, and correspondence, with versions and sources in each entry.'),`${list.length} ${t('项记录','records')}`)}${project?'':`<div class="collection-tools"><label class="search-field">${icon('search')}<input id="paper-search" type="search" value="${esc(query)}" placeholder="${t('找一篇论文','Find a paper')}" aria-label="${t('搜索论文','Search papers')}"></label><div class="filters" aria-label="${t('论文筛选','Paper filters')}"><button data-paper-filter="all" aria-pressed="${paperFilter==='all'}">${t('全部','All')}</button><button data-paper-filter="readable" aria-pressed="${paperFilter==='readable'}">${t('可站内阅读','Read here')}</button></div></div>`}<section id="work-results" class="work-list">${list.filter(w=>(paperFilter!=='readable'||w.pdf||project)&&[pick(w.title),w.fullTitle,w.context].join(' ').toLowerCase().includes(query.toLowerCase())).map(workRow).join('')||empty()}</section>${project?`<p class="quiet">${t('更多可公开的演示和具体贡献链接还在整理。','More public demonstrations and specific contribution links are still being gathered.')}</p>`:''}`;}
function empty(){return `<p class="empty" role="status">${t('没有找到，可以换个词。','No matches. Try another word.')}</p>`;}
function studyRecord(e){return `<article class="study-record"><div><span class="record-year">${esc(e.date)}</span><h3>${esc(pick(e.name))}</h3></div><div><p>${esc(pick(e.course))}</p><small>${esc(pick(e.status))} · ${esc(pick(e.extra))}</small></div></article>`;}
function experienceRecord(e){return `<details class="experience-record" id="record-${e.id}"><summary><time>${esc(e.date)}</time><span><strong>${esc(pick(e.role))}</strong><small>${esc(pick(e.name))}</small></span>${icon('chevron-right')}</summary><div class="record-body">${para(pick(e.body))}${works.filter(w=>w.experience===e.id||e.related?.includes(w.id)).map(w=>a('#work/'+w.id,esc(pick(w.title))+icon('arrow-up-right'),'related')).join('')}${(e.links??[]).map(([txt,url])=>a(url,esc(txt)+icon('external-link'),'related')).join('')}</div></details>`;}
function background(id){const org=organisations.find(o=>o.id===id);const groups=[['all',t('全部记录','All records')],['research',t('研究','Research')],['work',t('实习与工作','Work')],['service',t('服务与代表','Service')],['projects',t('项目参与','Programmes')]];const rows=experiences.filter(e=>(!org||org.records.includes(e.id))&&(backgroundFilter==='all'||experienceTags[e.id]?.includes(backgroundFilter)));return `${heading(t('学习与经历','Studies & experiences'),t('点一个标记，看看在那里的记录。','Choose a mark to explore the records from that place.'))}<section class="institution-surface" aria-label="${t('机构索引','Institution index')}">${organisations.map(o=>orgTile(o,false,o.id===id)).join('')}</section><section class="background-records" id="background-records"><header class="record-heading"><h2>${org?esc(pick(org.name)):t('先从学习说起','Studies first')}</h2>${org?a('#background',t('显示全部机构','Show all places')+icon('x'),'text-button'):''}</header><div class="study-list">${education.filter(e=>!org||org.study?.includes(e.id)).map(studyRecord).join('')}</div><div class="filters" aria-label="${t('经历筛选','Experience filters')}">${groups.map(([key,txt])=>`<button data-background-filter="${key}" aria-pressed="${backgroundFilter===key}">${txt}</button>`).join('')}</div><p class="result-count">${rows.length} ${t('段参与记录','experience records')}</p><div class="experience-list">${rows.map(experienceRecord).join('')||empty()}</div></section>${!org?`<details class="credentials"><summary>${t('会员与专业证书','Memberships & certification')}${icon('chevron-right')}</summary><p class="quiet">${t('依据 CV 记录；会员身份不代表任职，公开凭证尚未收录。','Recorded from the CV. Membership is not employment; public credentials are not yet included.')}</p>${credentials.map(c=>`<article><span>${esc(c.date)}</span><div><h3>${esc(c.issuer)}</h3><p>${esc(pick(c.title))}</p></div><small>${c.kind==='membership'?t('会员','Member'):t('证书','Certificate')}</small></article>`).join('')}</details>`:''}<p class="provenance">${t('任期和身份沿用所提供的 CV；个人叙述与公开凭证仍在补充。','Terms and roles follow the supplied CV; personal accounts and public evidence are still being added.')}</p>`;}
function workDetail(id){const w=works.find(w=>w.id===id);if(!w)return missing();return `${a('#'+(w.kind==='project'?'projects':'papers'),icon('arrow-left')+t('返回列表','Back to collection'),'back-link')}${heading(esc(pick(w.title)),esc(w.fullTitle),esc(w.year)+' · '+esc(w.context))}<div class="work-detail"><article class="reading-copy">${para(pick(w.body))}${w.authors?`<p class="authors">${esc(w.authors)}</p>`:''}<p class="version">${esc(pick(w.version))}</p>${links(w)}${w.experience?a('#experience/'+w.experience,t('相关经历','Related experience')+icon('arrow-up-right'),'related'):''}</article>${w.pdf?`<aside class="document-preview"><a href="#paper/${w.id}/1"><img src="${asset(w.thumb)}" alt="${esc(w.fullTitle)} ${t('首页','first page')}" width="380" height="510"></a><a class="primary-link" href="#paper/${w.id}/1">${t('在这里读论文','Read the paper here')}${icon('book-open' in icons?'book-open':'file-text')}</a><small>${w.pages} ${t('页 · 预印本','pages · Preprint')}</small></aside>`:''}</div>`;}
function paper(id,number){const w=papers.find(w=>w.id===id&&w.pdf);if(!w)return missing();const pg=Math.max(1,Math.min(w.pages,Number(number)||1));return `${a('#work/'+id,icon('arrow-left')+t('返回论文条目','Back to paper entry'),'back-link')}${heading(esc(pick(w.title)),esc(pick(w.version)))}<div class="reader-tools"><a href="#paper/${id}/${Math.max(1,pg-1)}" class="icon-button ${pg===1?'disabled':''}" aria-label="${t('上一页','Previous page')}" ${pg===1?'aria-disabled="true" tabindex="-1"':''}>${icon('chevron-left')}</a><label>${t('页','Page')}<select id="page-select" aria-label="${t('选择页码','Choose page')}">${Array.from({length:w.pages},(_,i)=>`<option ${i+1===pg?'selected':''} value="${i+1}">${i+1} / ${w.pages}</option>`).join('')}</select></label><a href="#paper/${id}/${Math.min(w.pages,pg+1)}" class="icon-button ${pg===w.pages?'disabled':''}" aria-label="${t('下一页','Next page')}" ${pg===w.pages?'aria-disabled="true" tabindex="-1"':''}>${icon('chevron-right')}</a><a class="original-pdf" href="${asset(w.pdf)}" target="_blank" rel="noopener noreferrer">${t('原 PDF','Original PDF')}${icon('external-link')}</a></div><p class="reader-hint">${t('逐页图像预览；复制文字或全文检索请打开原 PDF。','Page-image preview. Open the original PDF to copy or search text.')}</p><img class="paper-page" src="../explorations/assets/papers/${id}-${String(pg).padStart(2,'0')}.jpg" alt="${esc(pick(w.title))} · ${t('第','Page')} ${pg} ${t('页','')}" width="1000" height="1400">`;}
function notesList(){return `${heading(t('随手记','Notes'),t('还没写定，也先留在这里。','Not quite finished. Kept here anyway.'))}<div class="notebook-list">${notes.map((n,i)=>`<a class="notebook-entry" href="#note/${n.id}"><span class="note-date">${esc(n.date)} / ${t('整理稿','Draft')}</span><h2>${esc(pick(n.title))}</h2><p>${esc(pick(n.paragraphs)[0])}</p><span class="note-open">${t('接着读','Read on')}${icon('arrow-up-right')}</span></a>`).join('')}</div>`;}
function noteDetail(id){const n=notes.find(n=>n.id===id);if(!n)return missing();return `${a('#notes',icon('arrow-left')+t('返回随手记','Back to notes'),'back-link')}<article class="note-reading">${heading(esc(pick(n.title)),'',esc(n.date)+' · '+t('整理稿','Draft'))}${para(pick(n.paragraphs))}<p class="draft-disclosure">${t('据网站讨论整理，待本人修改；不是已发表文章。','Edited from website discussions, awaiting personal revision; not a published essay.')}</p></article>`;}
function experience(id){const e=experiences.find(e=>e.id===id);if(!e)return missing();return `${a('#background',icon('arrow-left')+t('返回学习与经历','Back to background'),'back-link')}${heading(esc(pick(e.role)),esc(pick(e.name)),esc(e.date))}<article class="reading-copy">${para(pick(e.body))}${works.filter(w=>w.experience===id||e.related?.includes(w.id)).map(w=>a('#work/'+w.id,esc(pick(w.title))+icon('arrow-up-right'),'related')).join('')}</article>`;}
function indexResults(){const data=[...works.map(w=>({name:pick(w.title),desc:w.context,href:'#work/'+w.id,type:w.kind==='paper'?t('论文','Paper'):t('项目','Project')})),...experiences.map(e=>({name:pick(e.role),desc:pick(e.name),href:'#experience/'+e.id,type:t('经历','Experience')})),...notes.map(n=>({name:pick(n.title),desc:n.date,href:'#note/'+n.id,type:t('随手记','Note')})),...education.map(e=>({name:pick(e.name),desc:pick(e.course),href:'#background/'+e.id,type:t('学习','Studies')}))];const found=data.filter(x=>(x.name+' '+x.desc).toLowerCase().includes(query.toLowerCase()));return `<p class="result-count" role="status">${found.length} ${t('项内容','items')}</p>${found.map(x=>`<a class="index-row" href="${x.href}"><span>${x.type}</span><div><strong>${esc(x.name)}</strong><small>${esc(x.desc)}</small></div>${icon('arrow-up-right')}</a>`).join('')||empty()}`;}
function index(){return `${heading(t('全部内容','All content'),t('也可以直接找，不必逐一翻开。','You can look something up without opening every collection.'))}<label class="search-field global-search">${icon('search')}<input type="search" id="global-search" value="${esc(query)}" aria-label="${t('搜索全部内容','Search all content')}" placeholder="${t('标题、机构或关键词','Title, place, or keyword')}"></label><section id="index-results">${indexResults()}</section>`;}
function missing(){return `${heading(t('这里没有这项内容','This entry could not be found'))}${a('#home',t('回到首页','Back home'),'primary-link')}`;}
function contents(){const [p,id,pg]=paths();return p==='home'?home():p==='papers'?workList():p==='projects'?workList(true):p==='background'?background(id):p==='work'?workDetail(id):p==='paper'?paper(id,pg):p==='notes'?notesList():p==='note'?noteDetail(id):p==='experience'?experience(id):p==='index'?index():missing();}
function render({focus=false,restore=false}={}){const key=location.hash||'#home';document.documentElement.lang=prefs.lang==='zh'?'zh-Hans':'en';document.documentElement.dataset.theme=prefs.theme;document.documentElement.dataset.large=prefs.large;document.body.dataset.collapsed=prefs.collapsed;document.body.dataset.mobileOpen=mobileOpen;document.body.dataset.scene=section();document.title=`${section()==='home'?'Tin-Yeh Huang':label(section())+' · Tin-Yeh Huang'}`;shell.innerHTML=`${nav()}<div class="site-body">${toolbar()}<main id="main" tabindex="-1" class="scene scene-${section()}">${contents()}</main><footer class="site-footer"><span>Tin-Yeh Huang</span><a href="#index">${t('全部内容','All content')}</a><small>${t('个人网站 · 本地预览','Personal website · Local preview')}</small></footer></div>`;syncMenu();syncAudio();if(focus)document.querySelector('#main').focus({preventScroll:true});if(restore)window.scrollTo(0,scrollPositions.get(key)||0);previousHash=key;}
function syncMenu(){document.body.dataset.mobileOpen=mobileOpen;const narrow=matchMedia('(max-width: 720px)').matches;document.querySelector('.site-body').inert=mobileOpen&&narrow;document.querySelector('.sidebar').inert=narrow&&!mobileOpen;}
function syncAudio(){document.querySelectorAll('[data-global-player]').forEach(el=>{el.innerHTML=audio.paused?'':musicButton(true);});document.querySelectorAll('[data-play]').forEach(b=>{b.innerHTML=icon(audio.paused?'play':'pause');b.setAttribute('aria-pressed',String(!audio.paused));b.setAttribute('aria-label',audio.paused?t('播放试听','Play preview'):t('暂停试听','Pause preview'));});document.querySelectorAll('[data-audio-state]').forEach(el=>{el.textContent=musicError||(audio.paused?t('约 30 秒 · 官方试听','~30 seconds · Official preview'):t('正在试听','Preview playing'));});}
shell.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-play')){musicError='';if(!audio.paused)audio.pause();else{if(!audio.src){audio.src=music.src;audio.volume=music.volume;}try{await audio.play();}catch{musicError=t('暂时无法播放，可打开歌曲来源。','Preview unavailable. Open the track source.');}}syncAudio();return;}
 if(b.hasAttribute('data-menu')){if(matchMedia('(max-width: 720px)').matches)mobileOpen=!mobileOpen;else prefs.collapsed=!prefs.collapsed;save();render();document.querySelector(matchMedia('(max-width: 720px)').matches&&!mobileOpen?'.mobile-menu':'.sidebar .nav-toggle')?.focus();return;}
 if(b.hasAttribute('data-close-menu')){mobileOpen=false;render();document.querySelector('.mobile-menu').focus();return;}
 if(b.hasAttribute('data-lang')){prefs.lang=prefs.lang==='zh'?'en':'zh';save();render();document.querySelector('[data-lang]').focus();return;}
 if(b.hasAttribute('data-theme')){prefs.theme=prefs.theme==='light'?'dark':'light';save();render();document.querySelector('[data-theme]').focus();return;}
 if(b.hasAttribute('data-size')){prefs.large=!prefs.large;save();render();document.querySelector('[data-size]').focus();return;}
 if(b.dataset.paperFilter){paperFilter=b.dataset.paperFilter;const y=scrollY;render();document.querySelector(`[data-paper-filter="${paperFilter}"]`).focus({preventScroll:true});window.scrollTo(0,y);return;}
 if(b.dataset.backgroundFilter){backgroundFilter=b.dataset.backgroundFilter;const y=scrollY;render();document.querySelector(`[data-background-filter="${backgroundFilter}"]`).focus({preventScroll:true});window.scrollTo(0,y);}
});
shell.addEventListener('input',e=>{if(e.target.id==='global-search'){query=e.target.value;document.querySelector('#index-results').innerHTML=indexResults();}if(e.target.id==='paper-search'){query=e.target.value;const list=papers.filter(w=>(paperFilter!=='readable'||w.pdf)&&[pick(w.title),w.fullTitle,w.context].join(' ').toLowerCase().includes(query.toLowerCase()));document.querySelector('#work-results').innerHTML=list.map(workRow).join('')||empty();}});
shell.addEventListener('change',e=>{if(e.target.id==='page-select')location.hash=`paper/${paths()[1]}/${e.target.value}`;});
shell.addEventListener('click',e=>{const l=e.target.closest('a');if(l?.getAttribute('aria-disabled')==='true'){e.preventDefault();return;}if(l?.getAttribute('href')?.startsWith('#')&&mobileOpen){mobileOpen=false;if(l.getAttribute('href')===(location.hash||'#home')){render();document.querySelector('#main').focus();}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&mobileOpen){mobileOpen=false;render();document.querySelector('.mobile-menu').focus();}if(e.key==='Tab'&&mobileOpen){const items=[...document.querySelectorAll('.sidebar button,.sidebar a')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.querySelector('#main').focus();});
window.addEventListener('hashchange',()=>{scrollPositions.set(previousHash,scrollY);const next=location.hash||'#home';const before=previousHash.split('/')[0],after=next.split('/')[0];queries.set(before,query);if(after!==before)query=queries.get(after)||'';if(after==='#background'&&next!==previousHash)backgroundFilter='all';mobileOpen=false;render({focus:true,restore:true});});
window.addEventListener('resize',syncMenu);
for(const event of ['play','pause','ended'])audio.addEventListener(event,syncAudio);
audio.addEventListener('error',()=>{musicError=t('试听连接不可用，可打开歌曲来源。','The preview is unavailable. Open the track source.');syncAudio();});
render();
